create table domain_events (id bigint generated by default as identity, occurred_at timestamp(6) with time zone not null, correlation_id varchar(50), event_id varchar(50) not null, metadata varchar(500), aggregate_id varchar(255) not null, aggregate_type varchar(255) not null, event_type varchar(255) not null, payload TEXT not null, primary key (id));
create table inventory_items (expiry_date date, quantity numeric(38,2), created_date timestamp(6), last_modified_date timestamp(6), version bigint not null, batch_number varchar(50), lpn varchar(50) not null, created_by varchar(255), last_modified_by varchar(255), location_code varchar(255) not null, product_sku varchar(255) not null, status varchar(255) check (status in ('IN_QUALITY_CHECK','AVAILABLE','RESERVED','PICKING','PACKED','DAMAGED','EXPIRED','SHIPPED')), tenant_id varchar(255) not null, primary key (lpn));
create table locations (current_volume numeric(38,2), current_weight numeric(38,2), max_volume numeric(38,2), max_weight numeric(38,2), version bigint, aisle varchar(255), column_name varchar(255), level_name varchar(255), location_code varchar(255) not null, zone_type varchar(255) check (zone_type in ('DRY_STORAGE','COLD_STORAGE','FROZEN_STORAGE','HAZMAT','RECEIVING_AREA','PICKING_AREA','DISPATCH_AREA','DOCK_DOOR','YARD','QUARANTINE')), primary key (location_code));
create table order_lines (allocated_quantity numeric(19,4), delivered_quantity numeric(19,4), picked_quantity numeric(19,4), promised_delivery_date date, requested_quantity numeric(19,4) not null, shipped_quantity numeric(19,4), created_date timestamp(6), last_modified_date timestamp(6), version bigint not null, inventory_item_id varchar(50), line_id varchar(50) not null, location_code varchar(50), order_id varchar(50) not null, notes varchar(500), created_by varchar(255), last_modified_by varchar(255), product_sku varchar(255) not null, status varchar(255) not null check (status in ('PENDING','ALLOCATED','PICKED','PACKED','SHIPPED','DELIVERED','CANCELLED','SHORT_PICKED')), tenant_id varchar(255) not null, primary key (line_id));
create table orders (promised_delivery_date date, promised_ship_date date, created_at timestamp(6) not null, created_date timestamp(6), last_modified_date timestamp(6), updated_at timestamp(6), version bigint not null, priority varchar(20), order_id varchar(50) not null, order_number varchar(50) not null unique, tracking_number varchar(100), cancellation_reason varchar(500), shipping_address varchar(500) not null, notes varchar(1000), cancelled_by varchar(255), carrier_id varchar(255), created_by varchar(255), customer_email varchar(255), customer_id varchar(255) not null, customer_name varchar(255) not null, last_modified_by varchar(255), status varchar(255) not null check (status in ('CREATED','CONFIRMED','PENDING','HOLD','ALLOCATED','PICKING','PACKED','SHIPPED','DELIVERED','CANCELLED')), tenant_id varchar(255) not null, warehouse_id varchar(255) not null, primary key (order_id));
create table processed_requests (created_at timestamp(6) not null, idempotency_key varchar(36) not null, primary key (idempotency_key));
create table products (active boolean not null, depth numeric(38,2), height numeric(38,2), weight numeric(38,2), width numeric(38,2), created_date timestamp(6), last_modified_date timestamp(6), version bigint not null, id uuid not null, created_by varchar(255), description varchar(255), last_modified_by varchar(255), name varchar(255), sku varchar(255), tenant_id varchar(255) not null, primary key (id));
create table stock_movement_logs (new_quantity numeric(38,2), old_quantity numeric(38,2), quantity numeric(38,2) not null, created_date timestamp(6), id bigint generated by default as identity, last_modified_date timestamp(6), timestamp timestamp(6) not null, version bigint not null, created_by varchar(255), last_modified_by varchar(255), lpn varchar(255) not null, reason varchar(255), sku varchar(255) not null, tenant_id varchar(255) not null, type varchar(255) not null check (type in ('RECEPCION','AJUSTE','MOVIMIENTO','SALIDA')), user_name varchar(255), primary key (id));
create table tenants (created_at timestamp(6), contact_email varchar(255), id varchar(255) not null, name varchar(255), status varchar(255) check (status in ('ACTIVE','SUSPENDED','TRIAL')), primary key (id));
create table users (created_date timestamp(6), id bigint generated by default as identity, last_modified_date timestamp(6), version bigint not null, created_by varchar(255), last_modified_by varchar(255), password varchar(255) not null, role varchar(255) check (role in ('SUPER_ADMIN','ADMIN','OPERATOR')), tenant_id varchar(255) not null, username varchar(255) not null unique, primary key (id));
create table warehouse_layouts (version integer not null, update_at timestamp(6), id varchar(255) not null, layout_json TEXT not null, tenant_id varchar(255) not null unique, primary key (id));
create index idx_aggregate_id on domain_events (aggregate_id);
create index idx_event_type on domain_events (event_type);
create index idx_occurred_at on domain_events (occurred_at);
create index idx_correlation_id on domain_events (correlation_id);
create index idx_loc_aisle on locations (aisle);
create index idx_loc_zone on locations (zone_type);
alter table if exists order_lines add constraint FK1smc0s578t2oih21yn9hw6usr foreign key (order_id) references orders;
